function ciwsGameDirectionV1(m,worldAz,el=0,distanceM=300){
  const b=shipGameAimBodyV1(worldAz,el),range=m.type==='GUN'?[-15,85]:[-20,80],q=ciwsGameConstraintsV1(m).direction(b.az,b.el,Math.min(300,Math.max(0,distanceM)));
  if(b.el<deg(range[0])-1e-8||b.el>deg(range[1])+1e-8)return {...q,ok:false,reason:'갑판 기준 고각 제한'};
  if(ciwsMountStateM(m).zM<=0)return {...q,ok:false,reason:'포탑 수몰'};
