computeShipStatus:
function computeShipStatus(runtime=ACTIVE_SHIP_RUNTIME){
    const getShipSystemDamage=(id,aggregate)=>shipSystemDamageB(runtime,id,aggregate);
    // Critical systems — WIP101 Stage 1: structured system aggregation, no display-name coupling.
    const cdcDmg = getShipSystemDamage('CDC');
    const bridge = Math.max(getShipSystemDamage('BRIDGE'),getShipSystemDamage('COMBAT_CENTER'));
    const spy = getShipSystemDamage('SPY_1D');
    const propulsion = (getShipSystemDamage('BOILER_1') + getShipSystemDamage('BOILER_2') + getShipSystemDamage('ENGINE_AFT')) / 3;
    const power = (getShipSystemDamage('GEN_1') + getShipSystemDamage('GEN_2')) / 2;
    const steering = getShipSystemDamage('STEERING');
    const flooding = getDamageFloodV1(runtime).summary().floodingPct;
    const longitudinalLoss=getShipLongitudinalStrengthV48Wip03(runtime).snapshot().summary.structuralLoss01*100;
    const hullStructuralDamage=100*(1-(1-clamp(getDamageFloodV1(runtime).hullDamagePct()/100,0,1))*(1-clamp(longitudinalLoss/100,0,1)));

    return {
      command: Math.max(cdcDmg, bridge),
      radar: spy,
      propulsion,
      power,
      steering,
      flooding,
      hullStructuralDamage,
      overall: Math.min(100, hullStructuralDamage * 1.2 + propulsion * 0.4 + power * 0.3 + cdcDmg * 0.1)
    };
  }

