function damageFloodTickV1(dt,runtime=ACTIVE_SHIP_RUNTIME){
    const own=runtime===ACTIVE_SHIP_RUNTIME,survivalModel=shipSurvivalB(runtime),nav=runtime.navigation;
    if(!(Number.isFinite(dt)&&dt>0))return;
    if(own){shipGamePreviousPoseV1=survivalModel.snapshot();shipGamePoseDtV1=dt;}else {runtime.previousPose=survivalModel.snapshot();runtime.poseDtS=dt;}
    const m=getDamageFloodV1(runtime),wave=getWaveFloodEnvironmentV48Wip05(runtime),power=damageFloodPowerV1(runtime),massLoss=shipMassLossB(runtime),strength=getShipLongitudinalStrengthV48Wip03(runtime);
    strength.step(dt,{flood:m.snapshot(),pose:survivalModel.snapshot(),dynamics:getShipDynamicsV15(runtime).snapshot(),speedMps:nav.speed});const structuralLoss01=strength.snapshot().summary.structuralLoss01;let left=dt;
    // Fixed substeps make water -> attitude -> hydraulic head a deterministic feedback loop.
    while(left>1e-10){const h=Math.min(left,1/120);left-=h;wave.step(h,{headingRad:nav.heading,speedMps:nav.speed});m.tick(h,shipEquipmentOfflineV1(runtime)?{GEN_1:0,GEN_2:0,GEN_3:0}:power,survivalModel.snapshot(),wave);damageControlStepV1(h,power,runtime);const floodSummary=m.summary();survivalModel.step({...floodSummary,...massLoss,structuralLoss01:Math.max(floodSummary.structuralLoss01||0,massLoss.structuralLoss01||0,structuralLoss01)},h);}
    m.setAttitude(survivalModel.snapshot());
    const survival=survivalModel.snapshot();const hp=survival.irreversible?0:Math.max(0,100-computeShipStatus(runtime).overall);if(own)shipHP=hp;else runtime.health.shipHP=hp;
    if(own&&survival.state!==damageFloodTickV1.lastState){if(survival.state!=='NORMAL')notify(survival.label+(survival.equipmentOffline?' · 장비 정지':''));damageFloodTickV1.lastState=survival.state;}
    if(own&&(shipEquipmentOfflineV1(runtime)||shipCrewV21?.combatUnavailable())){SPG62_ENGAGEMENT_STATE.clear();for(const m of ciws){m.firing=false;m.tracking=false;m.state='IDLE';m.turretRate=0;m.turretElRate=0;m.trackingTarget=null;}}
    if(own){updateShipSurvivalBannerV1(survival);updateDamageControlPanelV1();}
  }

